{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "In humans, melagatran oral bioavailability was lowered to only 0.9% after food intake, directly matching the fed-state condition and far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Melagatran has an oral bioavailability of only 3–7% in humans, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "The close structural analogue inogatran, a thrombin inhibitor with a basic guanidine and free carboxylate, had <5% oral bioavailability in healthy volunteers, supporting low F for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "DX-9065a, another benzamidine-containing drug, had 2–3% human oral bioavailability attributed to its strong basic amidino groups, a liability shared by the query's benzamidine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "AZD0837, a structurally related thrombin-inhibitor prodrug with masked polar groups, achieved 22–55% absolute bioavailability in humans, but this high-F result does not transfer to the free-acid/free-amidine query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct human data identify the query as melagatran, whose oral bioavailability is 3–7% and falls to 0.9% after food intake; the fed-state condition therefore strongly supports F < 20%. Close analogues with basic amidine/guanidine and free carboxylate groups also show very low oral bioavailability, while the only high-F analogue is a prodrug with masked polarity.",
  "evidence_gaps": [
    "No separate absolute bioavailability measurement for the exact query molecule under controlled fed conditions is present beyond the direct melagatran record, but that record is decisive for the fed-state prediction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

